import type { DefaultTheme } from "vitepress/theme";
import { useData } from "vitepress";
import { onBeforeUnmount, onMounted, ref } from "vue";
import VPButton from "vitepress/dist/client/theme-default/components/VPButton.vue";
import VPImage from "vitepress/dist/client/theme-default/components/VPImage.vue";
import GetStartedTabs from "./GetStartedTabs.vue";

interface HeroAction {
  theme?: "brand" | "alt";
  text: string;
  link: string;
  target?: string;
  rel?: string;
}

const { frontmatter: fm } = useData();

// Cycles the hero tagline's `.platform` pill through a few emitted platforms, each with its own
// glyph (set via the `--pantoken-glyph` custom property in pantoken.css) and casing convention.
const PLATFORMS = [
  { name: "web", label: "web" },
  { name: "react", label: "React" },
  { name: "vue", label: "Vue" },
  { name: "swift", label: "Swift" },
  { name: "android", label: "Android" },
  { name: "wordpress", label: "WordPress" },
] as const;

const heroTextRef = ref<HTMLElement | null>(null);
let cycleIntervalId: number | undefined;

onMounted(() => {
  const platformEl = heroTextRef.value?.querySelector<HTMLElement>(".platform");
  if (!platformEl || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  let index = PLATFORMS.findIndex((platform) => platformEl.classList.contains(platform.name));
  if (index < 0) index = 0;

  cycleIntervalId = window.setInterval(() => {
    index = (index + 1) % PLATFORMS.length;
    const next = PLATFORMS[index];

    platformEl.classList.add("is-fading");
    window.setTimeout(() => {
      platformEl.textContent = next.label;
      for (const platform of PLATFORMS) platformEl.classList.remove(platform.name);
      platformEl.classList.add(next.name);
      platformEl.classList.remove("is-fading");
    }, 200);
  }, 2600);
});

onBeforeUnmount(() => window.clearInterval(cycleIntervalId));
</script>"}

