replacements.oldString:
/* Chained platform class sets the glyph; this paints whatever `--pantoken-glyph` resolves to. */
&::before {
  content: "";
  display: inline-block;
  inline-size: 0.75em;
  block-size: 0.75em;
  vertical-align: -0.125em;
  margin-inline-end: 0.0625em;
  background: currentColor;
  -webkit-mask: var(--pantoken-glyph) center / contain no-repeat;
  mask: var(--pantoken-glyph) center / contain no-repeat;
}

&.web {
  --pantoken-glyph: var(--instui-icon-html5);
}

&.react {
  --pantoken-glyph: var(--instui-icon-react);
