async function measureAt(width) {
  await page.setViewportSize({ width, height: 900 });
  await page.evaluate(() => {
    for (let i = 1; i < 5000; i++) window.clearInterval(i);
  });
  const results = {};
  for (const [name, label, icon] of [["web","web","html5"], ["react","React","react"], ["wordpress","WordPress","wordpress"]]) {
    await page.evaluate(({ name, label, icon }) => {
      const el = document.querySelector(".platform");
      let glyph = el.querySelector(".platform-glyph");
      let lbl = el.querySelector(".platform-label");
      if (!glyph) {
        // reduced-motion or not-yet-mounted guard: bail, handled by caller
        return;
      }
      for (const p of ["web","react","vue","swift","android","wordpress"]) el.classList.remove(p);
      el.classList.add(name);
      glyph.style.setProperty("--pantoken-glyph", `var(--instui-icon-${icon})`);
      lbl.textContent = label;
      lbl.style.transform = "translateY(0)";
      const vp = el.querySelector(".platform-viewport");
      vp.style.transition = "none";
      vp.style.width = lbl.offsetWidth + "px";
    }, { name, label, icon });

    const info = await page.evaluate(() => {
      const line = document.querySelector(".platform-line");
      const textNode = Array.from(line.childNodes).find(n => n.nodeType === 3 && n.textContent.trim());
      const range = document.createRange();
      range.selectNodeContents(textNode);
      const accessibleBottom = range.getBoundingClientRect().bottom;

      const label = document.querySelector(".platform-label");
      const labelRange = document.createRange();
      labelRange.selectNodeContents(label.firstChild);
      const labelBottom = labelRange.getBoundingClientRect().bottom;

      const lineRect = line.getBoundingClientRect();
      return {
        diff: +(labelBottom - accessibleBottom).toFixed(2),
        lineRight: lineRect.right,
        viewportWidth: window.innerWidth,
        overflowsBy: +(lineRect.right - window.innerWidth).toFixed(2),
      };
    });
    results[name] = info;
  }
  return { width, results };
}

